#include "ec.hpp"
#include <filesystem>
#include <time.h>
struct TransportCount{U addsub=0,multiply=0,inverse=0;json wire()const{return{{"field_add_sub",addsub},{"field_multiply_including_inverse_power",multiply},{"field_inverse",inverse}};}};
struct TransportKernel{U r,v,u;};
U tmul(U x,U y,TransportCount&c){c.multiply++;return mul(x,y);}
U tadd(U x,U y,TransportCount&c){c.addsub++;return add(x,y);}
U tsub(U x,U y,TransportCount&c){c.addsub++;return sub(x,y);}
U tinv(U x,TransportCount&c){need(x!=0,"transport inverse");c.inverse++;U n=PRIME-2,r=1;for(;n;n>>=1,x=tmul(x,x,c))if(n&1)r=tmul(r,x,c);return r;}
Point transport_step(Point p,const TransportKernel&e,TransportCount&c){if(p.infinity)return{};U d=tsub(p.x,e.r,c);if(!d)return{};U di=tinv(d,c),x=tadd(p.x,tmul(e.v,di,c),c),y=tmul(p.y,tsub(1,tmul(e.v,tmul(di,di,c),c),c),c),u2=tmul(e.u,e.u,c);return{tmul(u2,x,c),tmul(tmul(u2,e.u,c),y,c),false};}
U tcpu(){timespec t{};need(clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&t)==0,"CPU clock");return U(t.tv_sec)*1000000000+U(t.tv_nsec);}
int main(int argc,char**argv){try{need(argc==2,"ROOT");std::string root=argv[1];need(!std::filesystem::exists(root+"/data/transport_measurements.jsonl"),"refuse overwrite");auto family=load(root+"/data/family.json"),fixtures=load(root+"/data/fixtures.json"),binding=load(root+"/TRANSPORT_FROZEN.json");std::ofstream log(root+"/data/transport_measurements.jsonl");U count=0;json paths=json::array();
for(const auto&node:family["nodes"]){int cid=node["id"],at=cid;std::vector<int>path;std::set<int>seen;while(at!=0){need(seen.insert(at).second,"transport path cycle");const auto&n=family["nodes"][at];int edge=n["discovery_edge"],parent=n["parent"];need(parent>=0&&family["edges"][edge]["source"]==parent&&family["edges"][edge]["target"]==at,"discovery path");path.push_back(edge);at=parent;}std::reverse(path.begin(),path.end());std::vector<TransportKernel>kernels;for(int edge:path){const auto&e=family["edges"][edge];kernels.push_back({val(e["kernel_x"]),val(e["v"]),val(e["u"])});}paths.push_back({{"curve",cid},{"path",path},{"steps",path.size()}});
for(const auto&row:fixtures["0"]){int id=row["id"];Point P=point(row["P"]),Q=point(row["Q"]),expectedP=point(fixtures[std::to_string(cid)][id]["P"]),expectedQ=point(fixtures[std::to_string(cid)][id]["Q"]);for(int repeat=0;repeat<5;repeat++){TransportCount counters;Point p=P,q=Q;U wall=ns(),cpu=tcpu();for(const auto&e:kernels){p=transport_step(p,e,counters);q=transport_step(q,e,counters);}cpu=tcpu()-cpu;wall=ns()-wall;need(p==expectedP&&q==expectedQ,"transport image mismatch");need(counters.multiply==174*path.size()&&counters.inverse==2*path.size(),"transport count identity");log<<json({{"curve",cid},{"instance",id},{"generator",row["generator"]},{"key_index",row["key_index"]},{"repeat",repeat},{"steps",path.size()},{"pair_wall_ns",wall},{"pair_process_cpu_ns",cpu},{"counters",counters.wire()},{"point_order_before",std::to_string(ORDER)},{"point_order_after",std::to_string(ORDER)},{"verified_public_P_Q_images",true},{"path_setup_excluded",true},{"identity_transport_at_source",cid==0}}).dump()<<'\n';count++;}}}
log.close();save(root+"/data/transport_paths.json",paths);save(root+"/data/transport_validation.json",{{"passed",true},{"records",count},{"curves",46},{"instances_per_curve",100},{"repetitions",5},{"binding",binding},{"all_images_match_frozen_fixtures",true},{"source_identity_transport_has_zero_field_operations",true},{"timing_class","CPU-only L0, concurrent BSGS; instrumented reference maps, not fastest-map timings"}});std::cout<<count<<" full source-to-curve transport measurements verified\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
